export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const FREE_TYPES = 3;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return 0;
  const distinctTypeCount = new Set(army.map((card) => card.monster)).size;
  return distinctTypeCount > FREE_TYPES ? 3 : 2;
};

