9	const BASE_POINTS = 1;
10	const FREE_TYPES = 3;
11	const POINTS_PER_TYPE_BEYOND_FREE = 2;
12	const POINTS_WITHIN_FREE_TYPES = 1;
13	
14	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
15	
16	const distinctMonsters = (army: Card[]): Set<string> =>
17	  new Set(army.map((card) => card.monster));
18	
19	/** Types the Sphinx surveys — every distinct monster except the Sphinx itself. */
20	const countTypesBesidesSphinx = (army: Card[]): number =>
21	  distinctMonsters(army).size - 1;
22	
23	const typeBonus = (typesBesidesSphinx: number): number =>
24	  typesBesidesSphinx > FREE_TYPES
25	    ? POINTS_PER_TYPE_BEYOND_FREE * (typesBesidesSphinx - FREE_TYPES)
26	    : POINTS_WITHIN_FREE_TYPES;
27	
28	export const scoreArmy = (army: Card[]): number => {
29	  if (!army.some(isSphinx)) return 0;
30	  return BASE_POINTS + typeBonus(countTypesBesidesSphinx(army));
31	};

